"use client";
/**
 * The entry sheet (V-03, the boards' Entry): a sheet over the dimmed page,
 * the kind's Fields generated by `entryForm`, done or planned, its time or
 * its span, a note; «Annulla» and «Salva». The server action arrives as a
 * prop (it reads the session; features never import app/). On an error it
 * hands back what was typed, and the form is drawn again from it.
 */
import { useActionState } from "react";
import { Field } from "@lifeos/kit";
import type { EntryForm } from "./entry-form";

export type SaveState = {
  /** Form name → the error in words. */
  errors: Record<string, string>;
  /** Form name → what was typed, to draw the form again. */
  values: Record<string, string>;
  /** Bumped on each answer, so the form is drawn again from `values`. */
  n: number;
};

export function EntrySheet({
  form,
  day,
  dayLabel,
  initial,
  closeHref,
  action,
}: {
  form: EntryForm;
  day: string;
  dayLabel: string;
  initial: Record<string, string>;
  closeHref: string;
  action: (state: SaveState, data: FormData) => Promise<SaveState>;
}) {
  const [state, submit, pending] = useActionState(action, {
    errors: {},
    values: initial,
    n: 0,
  });
  const v = state.values;
  const e = state.errors;
  return (
    <form key={state.n} action={submit} className="k-sheet-wrap k-screen">
      <a className="k-dim" href={closeHref} aria-label="Chiudi senza salvare" />
      <section className="k-sheet" role="dialog" aria-label={form.title}>
        <span className="handle" />
        <div className="k-sh">
          <h2>{form.title}</h2>
          <span className="k-meta">{dayLabel}</span>
        </div>
        <div className="k-sbody">
          <input type="hidden" name="kind" value={form.kind} />
          <input type="hidden" name="day" value={day} />
          <Field
            name="status"
            label="Stato"
            type="choice"
            required
            defaultValue={v["status"] ?? "done"}
            options={[
              { value: "done", label: "Fatto" },
              { value: "planned", label: "Previsto" },
            ]}
          />
          <div className={form.times.end ? "k-grid" : undefined}>
            <Field
              name="start"
              label={form.times.start}
              type="time"
              defaultValue={v["start"] ?? ""}
              error={e["start"]}
            />
            {form.times.end && (
              <Field
                name="end"
                label={form.times.end}
                type="time"
                defaultValue={v["end"] ?? ""}
                error={e["end"]}
              />
            )}
          </div>
          {form.fields.map((f) => (
            <Field key={f.name} {...f} defaultValue={v[f.name] ?? ""} error={e[f.name]} />
          ))}
          {form.more.length > 0 && (
            <details
              className="k-fold"
              open={form.more.some((f) => v[f.name] || e[f.name])}
            >
              <summary>Altre misure</summary>
              <div className="k-stack g4 k-foldin">
                {form.more.map((f) => (
                  <Field
                    key={f.name}
                    {...f}
                    defaultValue={v[f.name] ?? ""}
                    error={e[f.name]}
                  />
                ))}
              </div>
            </details>
          )}
          <Field
            name="note"
            label="Nota"
            type="text"
            placeholder="facoltativa"
            defaultValue={v["note"] ?? ""}
            error={e["note"]}
          />
          {e["form"] && (
            <p className="k-help" role="alert">
              {e["form"]}
            </p>
          )}
        </div>
        <div className="foot">
          <a className="k-btn secondary" href={closeHref}>
            Annulla
          </a>
          <button type="submit" className="k-btn primary" aria-busy={pending}>
            Salva
          </button>
        </div>
      </section>
    </form>
  );
}
